const fs   = require('fs');
const path = require('path');

const body = $input.first().json.body || $input.first().json;

const workflow = (body.workflow || 'Unknown').replace(/,/g, ' ');
const status   = (body.status   || 'unknown').replace(/,/g, ' ');
const details  = (body.details  || '').replace(/,/g, ';');
const ts       = new Date().toISOString().slice(0, 19).replace('T', ' ');

const logFile = '/data/scheduler/job_log.csv';

// Create file with header if it doesn't exist
if (!fs.existsSync(logFile)) {
  fs.mkdirSync(path.dirname(logFile), { recursive: true });
  fs.writeFileSync(logFile, 'timestamp,workflow,status,details\n', 'utf8');
}

// Append log entry
const row = `${ts},${workflow},${status},${details}\n`;
fs.appendFileSync(logFile, row, 'utf8');

return [{ json: { logged: true, entry: row.trim() } }];
